SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.discontinued_by_poe_id, o.order_provider_id, o.order_status, row_number() OVER(PARTITION BY s.stay_id ORDER BY s.intime) AS seq_num, dense_rank() OVER(PARTITION BY s.first_careunit ORDER BY s.intime) AS rank_careunit, percent_rank() OVER(PARTITION BY s.los ORDER BY s.los) AS percentile_los, ntile(4) OVER(PARTITION BY s.los) AS quartile_los, CASE WHEN d.icd_code = '41505' AND d.icd_version = '2015' THEN 'Yes' ELSE 'No' END AS heart_failure, COUNT(CASE WHEN d.icd_code = '41505' AND d.icd_version = '2015' THEN 1 END) OVER(PARTITION BY s.stay_id) AS num_heart_failures, COUNT(CASE WHEN d.icd_code = '41505' AND d.icd_version = '2015' THEN 1 END) OVER(PARTITION BY s.stay_id, s.first_careunit) AS num_heart_failures_per_unit, COUNT(CASE WHEN d.icd_code = '41505' AND d.icd_version = '2015' THEN 1 END) OVER(PARTITION BY s.stay_id, s.first_careunit, s.last_careunit) AS num_heart_failures_per_unit_and_dept FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN icustays s ON a.subject_id = s.subject_id JOIN orders o ON o.order_provider_id = p.subject_id WHERE p.gender = 'M' AND p.anchor_age = 48 AND p.anchor_year = 2015 AND p.anchor_year_group = '43-53' AND d.icd_code = '41505' AND d.icd_version = '2015' AND o.order_type = 'Infusion' AND o.order_subtype = 'Rate' AND o.transaction_type = 'New' AND o.discontinue_of_poe_id IS NULL AND o.discontinued_by_poe_id IS NULL;